def main():
    out = sys.argv[1]
    os.makedirs(out, exist_ok=True)
    for name, data in SMALL.items():
        with open(os.path.join(out, name), 'wb') as f:
            f.write(data)
    for name, make in STRESS.items():
        with open(os.path.join(out, name), 'w', encoding='utf-8') as f:
            f.write(make())


main()
